def gen(rng):
    def fmt(qs):
        return str(len(qs)) + "\n" + "\n".join(f"{a} {b}" for a, b in qs)
    N = 10 ** 18
    def pad(qs):
        # pad past 400 characters so the brute force is not run on huge values
        qs = list(qs)
        while len(fmt(qs)) <= 400:
            qs.append((rng.randint(10 ** 17, N), rng.randint(10 ** 17, N)))
        return fmt(qs)
    tests = [
        fmt([(2, 1)]),
        fmt([(4, 8)]),
        fmt([(1, 1)]),
        fmt([(1, 2), (2, 1), (2, 2), (3, 1), (1, 3)]),
        fmt([(a, b) for a in range(1, 8) for b in range(1, 8)]),
        fmt([(7, 6), (1, 1), (9, 2)]),
        pad([(N, N), (N, N - 1), (N - 1, N), (N, N - 2), (1, N), (N, 1)]),
    ]
    for _ in range(14):
        tests.append(fmt([(rng.randint(1, 30), rng.randint(1, 30)) for _ in range(rng.randint(1, 30))]))
    def big(size):
        qs = []
        for _ in range(size):
            if rng.random() < 0.5:
                x = rng.randint(1, N)
                qs.append((x, min(N, max(1, x + rng.choice([-1, 0, 1])))))
            elif rng.random() < 0.5:
                x = rng.randint(1, N)
                qs.append((x, min(N, max(1, x + rng.choice([-2, 2, -3, 3])))))
            else:
                qs.append((rng.randint(1, N), rng.randint(1, N)))
        return qs
    tests.append(fmt(big(50000)))
    tests.append(fmt(big(30000)))
    tests.append(fmt(big(2000)))
    return tests
